DROP TABLE IF EXISTS `sys_heartbeat_config`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `sys_heartbeat_config` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `country_code` varchar(10) DEFAULT NULL COMMENT '国家代码，NULL表示全局默认配置',
  `normal_interval` int NOT NULL DEFAULT '30' COMMENT '正常心跳间隔（秒），默认30s',
  `exception_interval` int NOT NULL DEFAULT '10' COMMENT '异常心跳间隔（秒），默认10s',
  `timeout_seconds` int NOT NULL DEFAULT '5' COMMENT '超时判定秒数，默认5s',
  `max_reconnect_times` int NOT NULL DEFAULT '3' COMMENT '单次最大重连次数，默认3次',
  `reconnect_interval` int NOT NULL DEFAULT '5' COMMENT '重连间隔（秒），默认5s',
  `reconnect_pause` int NOT NULL DEFAULT '60' COMMENT '重连失败后暂停时间（秒），默认60s',
  `notify_duration` int NOT NULL DEFAULT '10' COMMENT '异常持续X分钟后通知，默认10分钟',
  `notify_reconnect_times` int NOT NULL DEFAULT '10' COMMENT '重连超过X次后通知，默认10次',
  `disable_duration` int NOT NULL DEFAULT '30' COMMENT '持续重连失败X分钟后禁用接口，默认30分钟',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_country_code` (`country_code`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='心跳监测配置表';
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `sys_heartbeat_config`
--

LOCK TABLES `sys_heartbeat_config` WRITE;
/*!40000 ALTER TABLE `sys_heartbeat_config` DISABLE KEYS */;
/*!40000 ALTER TABLE `sys_heartbeat_config` ENABLE KEYS */;
UNLOCK TABLES;

--
-- Table structure for table `sys_heartbeat_log`
--

DROP TABLE IF EXISTS `sys_heartbeat_log`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `sys_heartbeat_log` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `account_id` bigint NOT NULL COMMENT '关联账号ID',
  `country_code` varchar(10) NOT NULL COMMENT '国家代码',
  `api_url` varchar(500) NOT NULL COMMENT '检测接口地址',
  `check_time` datetime NOT NULL COMMENT '心跳检测时间',
  `check_result` tinyint NOT NULL COMMENT '检测结果：0-正常，1-异常',
  `response_code` int DEFAULT NULL COMMENT 'HTTP响应状态码',
  `exception_type` varchar(100) DEFAULT NULL COMMENT '异常类型（TIMEOUT/LOGIN_EXPIRED/NETWORK_ERROR/CONFIG_MISMATCH）',
  `exception_msg` varchar(1000) DEFAULT NULL COMMENT '异常信息',
  `is_reconnect` tinyint NOT NULL DEFAULT '0' COMMENT '是否为重连记录：0-否，1-是',
  `reconnect_count` int DEFAULT NULL COMMENT '本次重连次数',
  `reconnect_result` tinyint DEFAULT NULL COMMENT '重连结果：0-成功，1-失败',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '记录时间',
  PRIMARY KEY (`id`),
  KEY `idx_account_id` (`account_id`),
  KEY `idx_country_code` (`country_code`),
  KEY `idx_check_time` (`check_time`),
  KEY `idx_check_result` (`check_result`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='心跳监测日志表（保留90天）';
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `sys_heartbeat_log`
--

LOCK TABLES `sys_heartbeat_log` WRITE;
/*!40000 ALTER TABLE `sys_heartbeat_log` DISABLE KEYS */;
/*!40000 ALTER TABLE `sys_heartbeat_log` ENABLE KEYS */;
UNLOCK TABLES;

--
-- Table structure for table `sys_i18n`
--

DROP TABLE IF EXISTS `sys_i18n`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `sys_i18n` (
  `id` varchar(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '主键UUID',
  `lang_key` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '翻译键（如user.title）',
  `lang_code` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '语言代码 zh_CN/en_US',
  `lang_value` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '翻译内容',
  `module` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '所属模块 user/role/menu/common',
  `status` tinyint(1) DEFAULT '0' COMMENT '状态（0正常 1停用）',
  `create_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '创建者',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '更新者',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '备注',
  `is_backend` tinyint DEFAULT NULL,
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `sys_i18n_unique` (`lang_key`,`lang_code`,`is_backend`,`status`) USING BTREE,
  KEY `idx_module` (`module`) USING BTREE COMMENT '模块索引'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='国际化翻译表';
/*!40101 SET character_set_client = @saved_cs_client */;

