--
-- Table structure for table `vehicle_info`
--

DROP TABLE IF EXISTS `vehicle_info`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `vehicle_info` (
  `vehicle_id` bigint NOT NULL AUTO_INCREMENT COMMENT '车辆ID',
  `vin` varchar(600) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'VIN码',
  `vehicle_model` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '车型代码',
  `factory_code` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '工厂代码',
  `material_no` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '整车物料号',
  `create_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '创建者',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '更新者',
  `update_time` datetime DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备注',
  `deleted` tinyint unsigned DEFAULT '0',
  `upload_status` tinyint NOT NULL DEFAULT '0' COMMENT '上传状态(0=未生成 1=已生成 2=未上传 3=上传中 4=上传成功 5=上传失败）',
  `validation_result` tinyint DEFAULT '0' COMMENT '校验结果(0=未校验 1=校验通过 2=校验失败)',
  `status` tinyint DEFAULT '0' COMMENT '状态(0=正常 1=停用)',
  `country` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '国家',
  `color` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '颜色',
  `secondary_color` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '双色的次色',
  `certificate_version` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '证书版本',
  `wvta_no` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'WVTA证书编号',
  `issue_date` datetime DEFAULT NULL COMMENT '发证日期',
  `json` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `xml_template_id` bigint DEFAULT NULL COMMENT '绑定的xml模板id',
  `vehicle_template_id` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'COC模板id',
  `factory_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '工厂名称',
  `validation_report_json` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `engine_number` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '发电机号',
  `motor_number` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '电机号',
  `brand` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '品牌',
  `weight` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '重量',
  `sale_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '销售名称',
  `tire` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '轮胎',
  `battery_number` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '电池号',
  `manufacture_date` datetime DEFAULT NULL COMMENT '制造日期',
  `tvv` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'tvv',
  `breakpoint_time` datetime DEFAULT NULL COMMENT '断点时间',
  `old_template_notice` tinyint DEFAULT '0' COMMENT '车辆信息引用的模版是否是老的模版通知是否发送0 未发送 1已发送',
  `temp_version` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '断点时间中设置的版本号',
  `generate_affirm` tinyint DEFAULT NULL COMMENT '生成确认:0未确认 1已确认',
  `upload_affirm` tinyint DEFAULT NULL COMMENT '上传确认:0未确认 1已确认',
  `project_name` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '项目名称',
  `customer_no` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '顾客编号',
  `tire_resistance_grade` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '轮胎滚阻等级',
  `first_material_flag` tinyint(1) NOT NULL DEFAULT '0' COMMENT '整车物料号首台车标记 0-否 1-是（该物料号下制造日期最早）',
  `first_template_flag` tinyint(1) NOT NULL DEFAULT '0' COMMENT '车辆模版首台车标记 0-否 1-是（该模版下制造日期最早）',
  `material_confirmed_by` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '物料号首台确认人',
  `material_confirmed_time` datetime DEFAULT NULL COMMENT '物料号首台确认时间',
  `template_confirmed_by` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '模版首台确认人',
  `template_confirmed_time` datetime DEFAULT NULL COMMENT '模版首台确认时间',
  `generate_affirm_notice` tinyint DEFAULT NULL COMMENT '生成确认通知是否已经发送：0未发送 1已发送',
  `upload_affirm_notice` tinyint DEFAULT NULL COMMENT '上传确认通知是否已经发送：0未发送 1已发送',
  `sale_company_name` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '销售公司名称',
  `model_no` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '车型',
  PRIMARY KEY (`vehicle_id`),
  UNIQUE KEY `vehicle_info_unique` (`vin`,`deleted`)
) ENGINE=InnoDB AUTO_INCREMENT=31 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='车辆信息表';
/*!40101 SET character_set_client = @saved_cs_client */;

